template <typename U>
struct DepType {
    template <typename V>
    void dependent_func() {}
};

template <typename T>
struct Wrapper {
    void execute(T obj) {
        // T is dependent. 'dependent_func' is a template member.
        // Needs 'template' keyword for disambiguation.
        obj.template dependent_func<int>();
    }
};

